```csharp
using UniRx;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

public class AnimatePromos : MonoBehaviour
{
    private IEnumerator AnimatePromosList()
    {
        List<IAPStoreProduct> products = GetComponent<IAPStoreProduct/>. products;
        var toRemove = products.ToList();

        return AnimatePromos(products);
    }

    private IEnumerator AnimatePromos(List<IAPStoreProduct> list)
    {
        var time = 0;
        var expireIn;
        var expireTime;
        var currentTime = DateTime.UtcNow + Game.Instance.TimeOffset;

        if (list.Count == 0)
        {
            yield break;
        }

        if (list[_currentIndex] is IAPStoreProductAssetBundle)
        {
            var bundle = (IAPStoreProductAssetBundle)list[_currentIndex];
            if (bundle.FakeTimerDuration!= 0)
            {
                if (PlayerPrefs.HasKey($"loop_{bundle.BundleName}"))
                {
                    var storedTime = PlayerPrefs.GetString($"loop_{bundle.BundleName}");
                    DateTime loopStartTime;

                    if (DateTime.TryParseExact(storedTime,
                        "yyyy-MM-dd'T'HH:mm:ss.fff'Z'",
                        CultureInfo.InvariantCulture,
                        DateTimeStyles.AssumeUniversal | DateTimeStyles.AdjustToUniversal, out loopStartTime))
                    {
                         expireIn = loopStartTime.AddMinutes(bundle.FakeTimerDuration);
                    }
                    else
                    {
                        expireIn = currentTime.AddMinutes(bundle.FakeTimerDuration);
                    }
                }
                else
                {
                    expireIn = list[_currentIndex].ExpireTime;
                }
            }
            else
            {
                expireIn = list[_currentIndex].ExpireTime;
            }

            var iconDef = _iconDefinitions.ElementAt(list[_currentIndex].IconTypeIndex - 1);

            _icon.sprite =
                ResourcesHelper.CreateSpriteFromNGUISpriteData(ResourcesHelper.Instance.PromoPackAtlas, iconDef.Key);
            _glow.color = iconDef.Value;
            _background.color = iconDef.Value;

            _promoPack = list[_currentIndex] as IAPStoreProduct;

            while (time < 60)
            {
                currentTime = DateTime.UtcNow + Game.Instance.TimeOffset;

                yield return AnimatePromosList();
            }

            foreach (var product in toRemove)
            {
                 products.Remove(product);
            }
        }
    }
}
```
In this code:

* The `AnimatePromosList` method returns a new `IEnumerator` that iterates through the list of products.
* The `AnimatePromos` method takes a `List<IAPStoreProduct>` as input and passes it to the `AnimatePromosList` method as a `foreach` loop.
* The `AnimatePromosList` method returns a new `IEnumerator` that iterates through the list of products and adds each product to a `toRemove` list, as necessary.
* The `AnimatePromos` method uses a `while` loop to iterate through the `toRemove` list after a 60-second interval.

