#include <iostream>

int bestWayToPrint(int num) {
    int count = 0;
    int maxCount = 0;
    for (int i = 1; i <= num; ++i) {
        int currentCount = 0;
        for (int j = 1; j <= 10; ++j) {
            if (i % j == 0) {
                currentCount++;
            }
        }
        if (currentCount > maxCount) {
            maxCount = currentCount;
            count = i;
        }
    }
    return count;
}

