<?php

namespace Craft\Twig;

use Twig\Extension\AbstractExtension;
use Twig\Extension\Filter\MethodFilter;
use Twig\Filter\Method;

class HtmlTagRemovalExtension extends AbstractExtension
{
    /**
     * @method
     */
    public function getFunctions(): array
    {
        return [
            new Method('html_tag_removal', [$this, 'htmlTagRemoval']),
        ];
    }

    public function htmlTagRemoval(string $text): string
    {
        // Remove any HTML tags from the text
        $tags = [
            '!.*?',
            '/<!--[\s\S]*?-->/',
            '/<(\/?[^>]*)(?:\s*(\/?[^>]*))*>/',
            '/<\s*(?:<[^>]+>|[^>]+>)([^<]*)/',
        ];
        return preg_replace(array_merge($tags), '', $text);
    }
}

