Here is the hook with the ability to close the window:

```tsx
import { useEffect, useState } from 'react';

interface TabMessage {
  from: string;
  text?: string;
}

function useInterTabCommunication() {
  const [data, setData] = useState<TabMessage | null>(null);

  useEffect(() => {
    window.addEventListener('message', (event) => {
      const message = event.data as TabMessage;
      if (message.text === 'close') {
        window.close();
      } else {
        setData(message);   
      }      
    });

    window.parent.postMessage({ from: 'tab1' } as TabMessage, '*');

    return () => {
      window.removeEventListener('message', null);
    }
  }, []);

  const sendData = (newData: TabMessage) => {
    window.parent.postMessage(newData, '*');    
  }

  return { data, sendData };
}
```

Within the event listener, I'm now checking:

- If the message.text is 'close', I call `window.close()` to close the current tab
- Otherwise, I call `setData()` as before

