```go
func sieveOfEratosthenes(n int) []int {
    // Create a boolean array "prime[0..n]" and initialize
    // all entries it as true.
    prime := make([]bool, n+1)
    for i := 2; i <= n; i++ {
        prime[i] = true
    }

    // Iterate through all numbers up to the square root of n.
    for p := 2; p*p <= n; p++ {
        // If prime[p] is still true after this loop, then p is a prime number.
        if prime[p] == true {
            // Update all multiples of p as composite numbers.
            for i := p * p; i <= n; i += p {
                prime[i] = false
            }
        }
    }

    // Create a new slice to store all prime numbers.
    primes := []int{}
    for p := 2; p <= n; p++ {
        if prime[p] == true {
            primes = append(primes, p)
        }
    }

    // Return the slice of prime numbers.
    return primes
}
```

To use this function, simply call `sieveOfEratosthenes(n)` where `n` is the upper limit of the prime numbers you want to find. The function will return a slice containing all prime numbers up to `n`.

