```c++
#include <iostream>
#include <algorithm>
using namespace std;
void quicksort(int arr[], int left, int right) {
    if (left < right) {
        int pivot = arr[left];
        int i = left - 1;
        for (int j = left; j < right; j++) {
            if (arr[j] <= pivot) {
                i++;
                swap(arr[i], arr[j]);
            }
        }
        swap(arr[i + 1], arr[right]);
        quicksort(arr, left, i);
        quicksort(arr, i + 1, right);
    }
}
int main() {
    int n;
    cout << "Enter the size of array: ";
    cin >> n;
    int arr[n];
    cout << "Enter the elements: ";
    for (int i = 0; i < n; i++) {
        cin >> arr[i];
    }
    cout << "Sorted array: ";
    quicksort(arr, 0, n - 1);
    cout << endl;
    return 0;
}
```
Explanation:
1. The `quicksort` function takes two parameters: `arr` and `left` and `right`. It initializes `left` and `right` to the first and last indices of the array respectively.
2. It then calls `quicksort` with the first half of the array, `arr`, and `left` as the starting index.
3. Inside the `quicksort` function, the `if` statement checks if the left index is less than or equal to the right index. If it is, the function swaps the element `arr[left]` with the element `arr[right]`, and then calls itself recursively with the left and right indices incremented by 1.
4. The function then calls itself with the left and right indices incremented by 1 again. This continues until the `left` index is equal to the `right` index.
5. The `quicksort` function returns the array after it has been sorted.

