use std::env;

fn main() {
    let args: Vec<String> = env::args().collect();
    let puzzle = &args[1];

    let mut solution = String::new();
    let mut char_map = [('a', 'z')];

    for c in puzzle.chars() {
        if c.is_uppercase() {
            let index = c as usize - 'A' as usize;
            solution.push(char_map[index].1);
