enum Expr {
    Num(i32),
    Var(char),
    Add(Box<Expr>, Box<Expr>),
    Sub(Box<Expr>, Box<Expr>),
    Mul(Box<Expr>, Box<Expr>),
    Div(Box<Expr>, Box<Expr>),
}

impl Expr {
    fn eval(&self, vars: &HashMap<char, i32>) -> i32 {
        match self {
            Expr::Num(n) => *n,
            Expr::Var(v) => *vars.get(v).unwrap(),
            Expr::Add(a, b) => a.eval(vars) + b.eval(vars),
            Expr::Sub(a, b) => a.eval(vars) - b.eval(vars),
            Expr::Mul(a, b) => a.eval(vars) * b.eval(vars),
            Expr::Div(a, b) => a.eval(vars) / b.eval(vars),
        }
    }
}

fn main() {
    let expr = Expr::Mul(
        Box::new(Expr::Add(Box::new(Expr::Var('x')), Box::new(Expr::Num(5)))),
        Box::new(Expr::Sub(Box::new(Expr::Var('y')), Box::new(Expr::Num(2))))
    );

    let vars = HashMap::from([('x', 10), ('y', 20)]);
    let result = expr.eval(&vars);
    println!("The result is: {}", result);
}
```

This defines an Expr enum to represent expressions, with variants for numbers, variables, addition, subtraction, multiplication and division.
The eval method evaluates an expression by looking up the values of variables in the provided HashMap and recursively evaluating subexpressions.

