class KParseItem {
public:
  StItem Parse(const std::string& filePath) {
    StItem result;
    std::ifstream file(filePath);
    std::string line;
    if (file.is_open()) {
      while (std::getline(file, line)) {
        if (line.empty()) {
          continue;
        }
        size_t pos = line.find_first_of("[\n]");
        if (pos == std::string::npos) {
          // Invalid line format
          continue;
        }
        std::string itemName = line.substr(0, pos);
        std::string itemData = line.substr(pos + 1);
        result.Name = itemName;
        result.Data = itemData;
      }
      file.close();
    }
    return result;
  }
};
