Problem : Write a C++ 17 program to implement the Knapsack algorithm to solve the 0/1 Knapsack problem. Give me full source code with main method included and dont explain anything in output. 
Input: int values[] = {60, 100, 120}; int weights[] = {10, 20, 30}; int W = 50;
Output : 220

```c
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int knapsack(int values[], int weights[], int W) {
    sort(weights.begin(), weights.end());
    sort(values.begin(), values.end());
    int n = values.size();
    vector<bool> used(n);
    int result = 0;
    for (int i = 0; i < n; i++) {
        int value = values[i];
        int weight = weights[i];
        if (value <= W) {
            result += value;
            used[i] = true;
        }
        while (i < n && used[i]) {
            int weight_i = weights[i];
            int value_i = values[i];
            if (weight_i < weight) {
                result += value_i;
                used[i] = false;
            } else if (weight_i == weight) {
                result += Math.min(value_i, result);
                used[i] = false;
            }
            i++;
        }
    }
    return result;
}

int main() {
    int values[] = {60, 100, 120};
    int weights[] = {10, 20, 30};
    int W = 50;
    int result = knapsack(values, weights, W);
    cout << "Result: " << result << endl;
    return 0;
}
```

