function parseNewsText(text) {
  if (!text) return [];

  const lines = text.split('\n');
  const result = [];

  for (const line of lines) {
    const lineSplit = line.split(':');

    if (lineSplit.length === 2) {
      const title = lineSplit[0].trim();
      const timestampOrDate = lineSplit[1].trim();
      result.push({
        title: title,
        hour_or_date: timestampOrDate,
      });
    } else if (lineSplit.length === 1) {
      const title = lineSplit[0].trim();
      const timestamp = lineSplit[0].match(/\d{2}:\d{2}/)[0].trim();
      result.push({
        title: title,
        hour_or_date: timestamp,
      });
    }
  }

  return result;
}

