Here is a code for a Google Chrome Extension that will:

1. Prompt the user to enter a product to search for
2. Search walmart.ca for the product in the background 
3. Show the 5 cheapest options in the extension popup

```js
// Listen for clicks on the browser action
chrome.browserAction.onClicked.addListener(function() {
  // Prompt the user to enter a product to search for
  let product = prompt("Enter a product to search for:");

  // Search walmart.ca for the product
  fetch(`https://www.walmart.ca/search?q=${product}`)
    .then(response => response.text())
    .then(html => {
      // Parse the HTML to get info on the 5 cheapest products
      let doc = new DOMParser().parseFromString(html, "text/html");
      let products = doc.querySelectorAll(".product-tile");
      let cheapProducts = [];
      for (let i = 0; i < 5; i++) {
        cheapProducts.push({
          title: products[i].querySelector(".product-name").textContent,
          price: products[i].querySelector(".price-main").textContent,
          rating: products[i].querySelector(".star-rating").textContent,
          description: products[i].querySelector(".product-description").textContent
        });
      }

      // Show the 5 cheapest products in the extension popup
      let popup = "";
      for (let product of cheapProducts) {
        popup += `
          <div>
            <b>${product.title}</b> 
            <div>Price: ${product.price}</div>
            <div>Rating: ${product.rating}</div>
            <div>${product.description}</div>
          </div>
          <hr>
        `;
      }
      chrome.storage.local.set({popup});
      chrome.runtime.openOptionsPage();
    });
});

// When the options page is opened, show the saved popup content
chrome.runtime.onMessage.addListener(function(request, sender, sendResponse) {
  if (request.type === "showPopup") {
    chrome.storage.local.get("popup", function(result) {
      document.querySelector("#popup").innerHTML = result.popup;
    });
  }
});
```

