#include <string.h>

int check_format(const char *input_str, const char **output_strings) {
    int i;
    const char *token;
    int num_values = 0;

    // check if the input string starts with a non-whitespace character
    if (input_str[0] != ',' && input_str[0] != ' ') {
        return 0; // not a valid input string
    }

    // count the number of values in the input string
    for (i = 0; i < strlen(input_str); i++) {
        if (input_str[i] == ',') {
            num_values++;
        }
    }

    // make sure the input string has at least 3 values
    if (num_values < 3) {
        return 0; // not a valid input string
    }

    // allocate memory for the output strings
    *output_strings = malloc((num_values - 1) * sizeof(char *));
    if (*output_strings == NULL) {
        return 0; // failed to allocate memory
    }

    // copy the output strings to the output_strings array
    token = strtok(input_str, ",");
    for (i = 0; i < num_values - 1; i++) {
        (*output_strings)[i] = strdup(token);
        if ((*output_strings)[i] == NULL) {
            return 0; // failed to allocate memory
        }
        token = strtok(NULL, ",");
    }
    (*output_strings)[num_values - 1] = strdup(token);
    if ((*output_strings)[num_values - 1] == NULL) {
        return 0; // failed to allocate memory
    }

    return 1; // the input string has the expected format
}
```
