```lua
def fibonacci(n, prev=0, next=1):
  if n == 0:
    return prev
  if n == 1:
    return next
  return fibonacci(n-1, prev, next) + fibonacci(n-2, prev, next)

for i in range(10):
  print(fibonacci(i))
```

