```sql
#include <iostream>
#include <cmath>
using namespace std;

int fibonacci(int n)
{
    int a = 0, b = 1, c;
    if (n == 0)
        return a;
    else if (n == 1)
        return b;
    else
        c = fibonacci(n-1) + fibonacci(n-2);
        return c;
}

int main()
{
    int n, i;
    cout << "Enter the value of n: ";
    cin >> n;
    cout << "The " << n << "th Fibonacci number is: ";
    for (i = 0; i < n; i++)
        cout << fibonacci(i) << " ";
    return 0;
}
```
