layout(local_size_x = WORKGROUP_SIZE, local_size_y = WORKGROUP_SIZE) in;

layout(set = 0, binding = 0) buffer MatrixA {
    float[] matrixA;
};

layout(set = 0, binding = 1) buffer MatrixB {
