#include <stdlib.h>

void *_realloc(void *ptr, unsigned int old_size, unsigned int new_size) {
    if (ptr == NULL) {
        return malloc(new_size);
    }

    if (new_size == old_size) {
        return ptr;
    }

    void *new_ptr = realloc(ptr, new_size);
    if (new_ptr == NULL) {
        free(ptr);
        return NULL;
