```javascript
QVector<QPair<int, int>> generateRandomEdges(QVector<int> nodes, int numEdges) {
    QVector<QPair<int, int>> edges;
    int count = 0;
    while (count < numEdges) {
        int i = qrand() % nodes.size();
        int j = qrand() % nodes.size();
        if (i == j) {
            continue;
        }
        edges.append(QPair<int, int>(i, j));
        count++;
    }
    return edges;
}
```
