```csharp
using System;

namespace FibonacciSequence
{
    class Program
    {
        static void Main(string[] args)
        {
            int termCount = 10; // number of terms to calculate
            int x = 10; // starting number
            int[] fib = new int[termCount]; // Fibonacci sequence array

            for (int i = 0; i < termCount; i++)
            {
                fib[i] = x;
                if (!IsPrime(fib[i]))
                {
                    x = fib[i] + fib[i - 1];
                }
            }

            Console.WriteLine("Fibonacci sequence up to " + termCount + ":");
            for (int i = 0; i < termCount; i++)
            {
                Console.WriteLine(fib[i]);
            }
        }

        static bool IsPrime(int n)
        {
            if (n <= 1)
            {
                return false;
            }

            for (int i = 2; i <= Math.Sqrt(n); i++)
            {
                if (n % i == 0)
                {
                    return false;
                }
            }

            return true;
        }
    }
}
```
