  var destSheet = SpreadsheetApp.openById('dest_sheet_id').getSheetByName('Sheet1');

  // Get data from source sheet
  var srcData = srcSheet.getDataRange().getValues();

  // Get data from destination sheet
  var destData = destSheet.getDataRange().getValues();

  // Cross reference the data
  var results = [];
  for(var i=0; i<srcData.length; i++) {
    for(var j=0; j<destData.length; j++) {
      if(srcData[i][0] == destData[j][0]) { // compare id columns
        results.push([srcData[i][0], srcData[i][1], destData[j][1]]); 
      }
    }
  }

  // Pivot the results
  var pivotData = [];
  pivotData.push(["ID", "Source Value", "Destination Value"]);

  for(var k=0; k<results.length; k++) {
    pivotData.push([results[k][0], results[k][1], results[k][2]]); 
  }

  // Output pivot table to new sheet
  var outputSheet = SpreadsheetApp.openById('output_sheet_id').getSheetByName('Pivot');
  outputSheet.getRange(1,1,pivotData.length, pivotData[0].length).setValues(pivotData);

}
