```javascript
var game = new Phaser.Game(800, 600, Phaser.AUTO, 'game');

var hiddenObjects = [
    { name: 'NAME_1', x: 200, y: 100 },
    { name: 'Eraser', x: 300, y: 200 },
    { name: 'Ruler', x: 400, y: 300 }
];

var currentObject = null;
var hint = '';

game.state.add('hidden-objects', {
    preload: function() {
        // Load images for the objects
        hiddenObjects.forEach(function(object) {
            game.load.image(object.name, object.x, object.y, 50, 50);
        });
    },
    create: function() {
        // Create the objects
        hiddenObjects.forEach(function(object) {
            game.add.sprite(object.x, object.y, object.name);
        });
    },
    update: function() {
        if (currentObject === null && hint !== '') {
            currentObject = hiddenObjects.find(function(object) {
                return object.name === hint;
            });
            if (currentObject !== null) {
                hint = '';
            }
        }

        if (currentObject !== null) {
            game.setCursor(currentObject.x + 50, currentObject.y + 50);
            game.input.overwriteCallback = function() {
                if (hint !== '') {
                    hint = '';
                }
                currentObject = null;
            };
        }
    }
});

