    public Cell(int x, int y, string name)
    {
        X = x;
        Y = y;
        Name = name;
    }
}

public class QuadTree
{
    private readonly Cell[] _cells;
    private readonly int _width;
    private readonly int _height;

    private readonly Func<Cell, bool> _cellFilter;

    private readonly List<Cell> _selectedCells = new List<Cell>();

    public QuadTree(int width, int height, Func<Cell, bool> cellFilter)
    {
        _width = width;
        _height = height;
        _cells = new Cell[_width * _height];
        _cellFilter = cellFilter;
    }

    public void AddCell(Cell cell)
    {
        if (_cellFilter(cell))
        {
            _cells[_cells.Length - 1] = cell;
            _selectedCells.Add(cell);
        }
    }

    public void RemoveCell(Cell cell)
    {
        _selectedCells.Remove(cell);
        for (int i = 0; i < _cells.Length - 1; i++)
        {
            if (_cells[i] == cell)
            {
                _cells[i] = _cells[_cells.Length - 1];
                _cells[_cells.Length - 1] = null;
            }
        }
    }

    public IEnumerable<Cell> GetSelectedCells()
    {
        return _selectedCells;
    }

    public void ClearSelection()
    {
        _selectedCells.Clear();
    }

    public void OnClicked(Cell cell)
    {
        if (_cellFilter(cell))
        {
            _selectedCells.Add(cell);
            var eventHandler = Clicked;
            if (eventHandler != null)
            {
                eventHandler(this, cell);
            }
        }
    }
}

public class World
