Here is an example of the quicksort algorithm implemented in C++:
```c++
#include <iostream>
#include <vector>

using namespace std;

void quicksort(vector<int> &arr, int low, int high) {
  if (low < high) {
    int pivot = partition(arr, low, high);
    quicksort(arr, low, pivot - 1);
    quicksort(arr, pivot + 1, high);
  }
}

int partition(vector<int> &arr, int low, int high) {
  int pivot = arr[high];
  int i = low - 1;
  for (int j = low; j <= high - 1; j++) {
    if (arr[j] <= pivot) {
      i++;
      swap(arr[i], arr[j]);
    }
  }
  swap(arr[i + 1], arr[high]);
  return i + 1;
}

int main() {
  vector<int> arr = {3, 4, 1, 5, 2};
  int n = arr.size();
  quicksort(arr, 0, n - 1);
  for (int i = 0; i < n; i++) {
    cout << arr[i] << " ";
  }
  return 0;
}
```
This implementation of quicksort uses the standard partition scheme, where the pivot element is chosen as the last element in the array. The pivot is then used to divide the array into two subarrays, with elements less than the pivot on the left and elements greater than the pivot on the right. The subarrays are then recursively sorted using the same partition and quicksort procedures. The pivot element is placed at the end of the sorted subarray.

In this example, the input array is [3, 4, 1, 5, 2], and the output will be [1 2 3 4 5].

