  lastActivity = Date.now();
}

// Set up interval to update last activity time
setInterval(() => {
  lastActivity = Date.now();
}, 5000);

// Add event listeners to reset inactivity timer
document.body.addEventListener('click', resetInactivityTimer);
document.documentElement.addEventListener('keyup', resetInactivityTimer);
```
With these steps, the user will be automatically logged out after a certain period of inactivity, and any click or type events will reset the inactivity timer.

