    List<string> anagrams = new List<string>();

    foreach (string word in words)
    {
        string sortedWord = "";
        for (int i = 0; i < word.Length; i++)
        {
            sortedWord += word[i];
        }

        bool isAnagram = true;
        for (int i = 0; i < sortedWord.Length; i++)
        {
            if (sortedWord[i] != input[i % input.Length])
            {
