fn bubble_sort(vector: &Vec<i32>) -> Vec<i32> {
    let mut copy = vector.clone();
    let mut i = 0;
    while i < copy.len() {
        let pivot = copy[i];
        let j = i + 1;
        while j < copy.len() && copy[j] > pivot {
            let temp = copy[j];
            copy[j] = copy[i];
            copy[i] = temp;
            i += 1;
            j += 1;
        }
    }
    copy
}
```
