Here is an example of C\# code for platform-independent audio recording in MAUI using the `` MAudio.AudioSource `` class:


```csharp
using System.Runtime.InteropServices;

public class AudioRecorder
{
    [DllImport("<platform_name>")]
    private static extern IntPtr CreateAudioSource(short sampleRate, short channels, short format);

    [DllImport("<platform_name>")]
    private static extern int AllocBuffer(short bufferSize);

    [DllImport("<platform_name>")]
    private static extern short ReadAudioData(IntPtr audioSource, short bufferSize, short format, short channels, short sampleRate);

    [DllImport("<platform_name>")]
    private static extern int WriteAudioData(IntPtr audioSource, short bufferSize, short format, short channels, short sampleRate);

    [DllImport("<platform_name>")]
    private static extern void FreeAudioSource(IntPtr audioSource);

    private IntPtr audioSource;
    private short sampleRate;
    private short channels;
    private short format;

    public AudioRecorder(short sampleRate, short channels, short format)
    {
        this.audioSource = CreateAudioSource(sampleRate, channels, format);
        this.sampleRate = sampleRate;
        this.channels = channels;
        this.format = format;
    }

    public void Record()
    {
        int bufferSize = AllocBuffer(AudioSource.MaxBufferSize);
        short buffer = new short[bufferSize];

        for (int i = 0; i < bufferSize; i++)
        {
            short data = ReadAudioData(audioSource, bufferSize, format, channels, sampleRate);
            buffer[i] = data;
        }

        WriteAudioData(audioSource, bufferSize, format, channels, sampleRate);

        FreeAudioSource(audioSource);
    }
}

```

Note that this is just an example and you will need to replace `` <platform_name> `` with the name of the platform you are targeting. You will also need to add the appropriate platform-specific libraries and frameworks to your project.

