```sql
DECLARE
  start_date DATE;
  end_date DATE;
  years NUMBER(10) := 0;
BEGIN
  IF end_date > start_date THEN
  BEGIN
    SET years := years + (end_date - start_date) * 100.0 / 365.25;
  END
  ELSE
  BEGIN
    SET years := 0;
  END
