Here's a basic implementation of bubble sort in C++:
```c
#include <iostream>
#include <algorithm>

using namespace std;

void bubbleSort(int arr[], int n) {
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - i - 1; j++) {
            if (arr[j] > arr[j + 1]) {
                swap(arr[j], arr[j + 1]);
            }
        }
    }
}

int main() {
    int arr[] = {5, 4, 3, 2, 1};
    int n = sizeof(arr) / sizeof(arr[0]);
    cout << "Before sorting: ";
    for (int i = 0; i < n; i++) {
        cout << arr[i] << " ";
    }
    cout << endl;

    bubbleSort(arr, n);

    cout << "After sorting: ";
    for (int i = 0; i < n; i++) {
        cout << arr[i] << " ";
    }
    cout << endl;

    return 0;
}
```
This code defines a function `bubbleSort` that takes an array `arr` and its size `n` as arguments. The function uses two nested loops to compare adjacent elements in the array and swap them if they are in the wrong order. The `main` function demonstrates how to call the `bubbleSort` function and print the sorted and unsorted arrays.

