export const setTokenCookie = (
  { $cookies }: NuxtAppOptions,
  tokens: TokenType
) => {
  const setCookieWithExpiration = (
    key: string,
    value: string,
    expiration: number
  ) => {
    $cookies.set(key, value, {
      path: '/',
      expires: new Date(expiration * 1000) // 만료 시간을 밀리초로 변환하여 설정
    })
  }

  const decodeTokenPayload = (token: string) => {
    const base64Payload = token.split('.')[1]
    const payload = Buffer.from(base64Payload, 'base64')
    return JSON.parse(payload.toString())
  }

  const { token, refreshToken } = tokens
  const tokenPayload = decodeTokenPayload(token)
  const refreshTokenPayload = decodeTokenPayload(refreshToken)

  setCookieWithExpiration('d_a', token, tokenPayload.exp)
  setCookieWithExpiration('d_r', refreshToken, refreshTokenPayload.exp)
}

