```js
function cronParser(cronExpr) {
  // Split the expression into fields
  var fields = cronExpr.split(' ');

  // Check if the expression is valid
  if (fields.length !== 7) {
    throw new Error('Invalid cron expression');
  }

  // Get the timespan for each field
  var seconds = getFieldValues(fields[0], 0, 59);
  var minutes = getFieldValues(fields[1], 0, 59);
  var hours = getFieldValues(fields[2], 0, 23);
  var days = getFieldValues(fields[3], 1, 31);
  var months = getFieldValues(fields[4], 1, 12);
  var weeks = getFieldValues(fields[5], 0, 53);
  var years = getFieldValues(fields[6], 1970, 2099);

  // Generate all execution times
  var times = [];
  generateTimes(seconds, minutes, hours, days, months, weeks, years, times);

  // Return the last 10 execution times
  return times.slice(-10);

  // Helper functions

  function getFieldValues(field, start, end) {
    var values;
    if (field.includes('*')) {
      values = [];
      for (var i = start; i <= end; i++) {
        values.push(i); 
      }
    } else {
      values = field.split(',').map(x => parseInt(x));
    }
    return values;
  }

  function generateTimes(seconds, minutes, hours, days, months, weeks, years, times) {
    if (seconds.length === 0 && minutes.length === 0 && ... ) {
      return;
    }

    var second = seconds.shift();
    var minute = minutes.shift();
    // ...

    var date = new Date(year, month - 1, day, hour, minute, second);
    times.push(date);

    generateTimes(seconds, minutes, ...);
    seconds.unshift(second);
    minutes.unshift(minute);
    // ...
  }
}
```

This method parses the cron expression by splitting it into the 7 fields. It then gets the values for each field and recursively generates all possible execution times. It returns the last 10 times in the format compatible with IE browsers.

