function formValidator(form) {
  let requiredFields = ["fullname", "email", "phone"];
  let emailRegex = /^\w+@[a-zA-Z_]+?\.[a-zA-Z]{2,3}$/;
  let phoneRegex = /^\d{10}$/;

  let isValid = true;
  for (let i = 0; i < form.elements.length; i++) {
    let element = form.elements[i];
    if (element.type === "text" && requiredFields.includes(element.name)) {
      if (!element.value) {
        isValid = false;
        break;
      }
    } else if (element.type === "email" && element.name === "email") {
      if (!emailRegex.test(element.value)) {
        isValid = false;
        break;
      }
    } else if (element.type === "tel" && element.name === "phone") {
      if (!phoneRegex.test(element.value)) {
        isValid = false;
        break;
      }
    }
  }

  return isValid;
}
```
