use polars::{DataFrame, GroupBy};
use std::fmt;

fn print_grouped_items(gb: &GroupBy<i32, i32>, sorted: bool) -> fmt::Result {
    let mut res = String::new();
    let mut prefix = String::new();

    for (i, group) in gb.groups_iter() {
        let name = if prefix.is_empty() {
            format!("{:?}", i)
        } else {
            format!("{}:", prefix)
        };
        prefix.push_str(name);
        let items = group.iter().map(|row| format!("{}: {}", row.get(0), row.get(1))).collect::<Vec<_>>();
        res.push_str(&items.join("\n"));
    }

    if sorted {
        res.sort();
    }

    Ok(res)
}

