```sql
// JCL job to copy dataset to tape

DATA DIVISION.
WORKING STORAGE SECTION.
01 INPUT-FILE    PARM('dataset.dat')    TYPE(*CHAR) LEN(100).
01 OUTPUT-FILE   PARM('output.dat')    TYPE(*CHAR) LEN(100).
01 TAPE-NAME     PARM('tape01.dat')    TYPE(*CHAR) LEN(20).

PROCEDURE DIVISION.

// Open input dataset and tape
OPEN INPUT INPUT-FILE
CHAIN VAR(&INPUT-FILE)

OPEN OUTPUT OUTPUT-FILE
CHAIN VAR(&OUTPUT-FILE)

