```c
#include <stdio.h>
#include <stdlib.h>

void mergeSort(int array[], int left[], int right[]) {
    int n1 = left - array;
    int n2 = right - array;

    int L[n1], R[n2];

    for (int i = 0; i < n1; i++) {
        L[i] = array + i;
    }
    for (int j = 0; j < n2; j++) {
        R[j] = array + (j + 1);
    }

    int i = 0, j = 0, k = 0;

    while (i < n1 && j < n2) {
        if (L[i] < R[j]) {
            array[k++] = L[i++];
        }
        else {
            array[k++] = R[j++];
        }
    }

    while (i < n1) {
        array[k++] = L[i++];
    }

    while (j < n2) {
        array[k++] = R[j++];
    }
}

int main() {
    int array[] = {3, 7, 1, 5, 2};
    int size = sizeof(array) / sizeof(array[0]);

    printf("Before sorting: ");
    for (int i = 0; i < size; i++) {
        printf("%d ", array[i]);
    }
    printf("\n");

    mergeSort(array, size - 1, size - 1);

    printf("After sorting: ");
    for (int i = 0; i < size; i++) {
        printf("%d ", array[i]);
    }
    printf("\n");

    return 0;
}
```
