#include <iostream>
#include <vector>
#include <numeric>

double calculate_mean(const std::vector<int>& list_of_ints) {
    if (list_of_ints.empty()) {
        return 0;
    }
    double sum = std::accumulate(list_of_ints.begin(), list_of_ints.end(), 0);
    return sum / list_of_ints.size();
