    return &RingBuffer{
        buffer: buffer.New(size),
        start: 0,
        end:  0,
    }
}

func (r *RingBuffer) Write(data []byte) int {
    if r.start == r.end {
        r.buffer.Write(data)
        r.end = (r.end + 1) % r.buffer.Size
        return len(data)
    }
    r.buffer.Write(data[r.start:r.end])
    r.start = (r.start + 1) % r.buffer.Size
    return len(data)
}

func (r *RingBuffer) Read(data []byte) int {
    data = r.buffer.Read(data)
    if r.start == r.end {
        r.end = (r.end + 1) % r.buffer.Size
        return len(data)
    }
    r.start = (r.start + 1) % r.buffer.Size
    return len(data)
}

