To encrypt the cookie in the Express server and decrypt it in the Go server, you can use a symmetric encryption algorithm like AES (Advanced Encryption Standard). Here's how to do it:

1. In the Express server, install the `crypto` package:

```bash
npm install crypto
```

2. Update the `server.ts` file in the Express server to encrypt the cookie value before setting it:

```typescript
import express, { Request, Response } from 'express';
import cookieParser from 'cookie-parser';
import crypto from 'crypto';

const app = express();
app.use(cookieParser());

const secretKey = 'your_secret_key_here'; // Must be 32 bytes for AES-256
const algorithm = 'aes-256-cbc';

function encrypt(text: string): string {
  const iv = crypto.randomBytes(16);
  const cipher = crypto.createCipheriv(algorithm, Buffer.from(secretKey), iv);
  const encrypted = Buffer.concat([cipher.update(text), cipher.final()]);
  return iv.toString('hex') + ':' + encrypted.toString('hex');
}

app.get('/set-cookie', (req: Request, res: Response) => {
  const cookieValue = 'cookieValue';
  const encryptedCookieValue = encrypt(cookieValue);

  res.cookie('sharedCookie', encryptedCookieValue, {
    httpOnly: true,
    secure: true, // Set to true if using HTTPS
    domain: '.yourdomain.com', // Replace with your domain or subdomain
    maxAge: 24 * 60 * 60 * 1000, // Cookie expiry time (in milliseconds)
  });
  res.send('Encrypted cookie has been set');
});

const PORT = 3000;
app.listen(PORT, () => {
  console.log(`Express app listening on port ${PORT}`);
});
```

3. In the Go server, install the `crypto` package:

```bash
go get golang.org/x/crypto
```

4. Update the `main.go` file in the Go server to decrypt the cookie value:

```go
package main

import (
	"crypto/aes"
	"crypto/cipher"
	"encoding/hex"
	"fmt"
	"net/http"
	"strings"
)

const secretKey = "your_secret_key_here"

func decrypt(encryptedText string) (string, error) {
	parts := strings.Split(encryptedText, ":")
	if len(parts) != 2 {
		return "", fmt.Errorf("Invalid encrypted text format")
	}

	iv, err := hex.DecodeString(parts[0])
	if err != nil {
		return "", err
	}

	encryptedData, err := hex.DecodeString(parts[1])
	if err != nil {
		return "", err
	}

	block, err := aes.NewCipher([]byte(secretKey))
	if err != nil {
		return "", err
	}

	if len(encryptedData) < aes.BlockSize {
		return "", fmt.Errorf("Encrypted data is too short")
	}

	mode := cipher.NewCBCDecrypter(block, iv)
	mode.CryptBlocks(encryptedData, encryptedData)

	return string(encryptedData), nil
}

func main() {
	http.HandleFunc("/get-cookie", func(w http.ResponseWriter, r *http.Request) {
		cookie, err := r.Cookie("sharedCookie")
		if err != nil {
			fmt.Fprintf(w, "Error retrieving cookie: %v", err)
			return
		}

		decryptedCookieValue, err := decrypt(cookie.Value)
		if err != nil {
			fmt.Fprintf(w, "Error decrypting cookie: %v", err)
			return
		}

		fmt.Fprintf(w, "Decrypted cookie value: %s", decryptedCookieValue)
	})

	http.ListenAndServe(":8080", nil)
}
```

Now, when you set the encrypted cookie in the Express server by visiting `/set-cookie`, you can retrieve and decrypt the cookie value in the Go server by visiting `/get-cookie`. Make sure to use the same secret key in both the Express server and the Go server for encryption and decryption.

To use JSON Web Tokens (JWTs) for secure communication between the Express server and the Go server, you will need to sign and verify JWTs in both applications. Here's how to do it:

1. In the Express server, install the `jsonwebtoken` package:

