```typescript
import express, { Request, Response } from 'express';
import cookieParser from 'cookie-parser';
import jwt from 'jsonwebtoken';

const app = express();
app.use(cookieParser());

const secretKey = 'your_secret_key_here';
const jwtExpirySeconds = 24 * 60 * 60; // 1 day

app.get('/set-jwt', (req: Request, res: Response) => {
  const payload = {
    data: 'your_data_here',
  };

  const token = jwt.sign(payload, secretKey, { expiresIn: jwtExpirySeconds });

  res.cookie('sharedJWT', token, {
    httpOnly: true,
    secure: true, // Set to true if using HTTPS
    domain: '.yourdomain.com', // Replace with your domain or subdomain
    maxAge: jwtExpirySeconds * 1000, // Cookie expiry time (in milliseconds)
  });
  res.send('JWT has been set');
});

const PORT = 3000;
app.listen(PORT, () => {
  console.log(`Express app listening on port ${PORT}`);
});
```

3. In the Go server, install the `jwt-go` package:

```bash
go get github.com/golang-jwt/jwt/v4
```

4. Update the `main.go` file in the Go server to verify the JWT and read its payload:

```go
package main

import (
	"fmt"
	"net/http"
	"strings"

	"github.com/golang-jwt/jwt/v4"
)

const secretKey = "your_secret_key_here"

func verifyAndReadJWT(tokenString string) (jwt.MapClaims, error) {
	token, err := jwt.Parse(tokenString, func(token *jwt.Token) (interface{}, error) {
		return []byte(secretKey), nil
	})

	if err != nil {
		return nil, err
	}

	if !token.Valid {
		return nil, fmt.Errorf("Invalid token")
	}

	claims, ok := token.Claims.(jwt.MapClaims)
	if !ok {
		return nil, fmt.Errorf("Invalid claims format")
	}

	return claims, nil
}

func main() {
	http.HandleFunc("/get-jwt", func(w http.ResponseWriter, r *http.Request) {
		cookie, err := r.Cookie("sharedJWT")
		if err != nil {
			fmt.Fprintf(w, "Error retrieving JWT: %v", err)
			return
		}

		claims, err := verifyAndReadJWT(cookie.Value)
		if err != nil {
			fmt.Fprintf(w, "Error verifying and reading JWT: %v", err)
			return
		}

		fmt.Fprintf(w, "JWT payload: %v", claims)
	})

	http.ListenAndServe(":8080", nil)
}
```

Now, when you set the JWT in the Express server by visiting `/set-jwt`, you can verify and read the JWT payload in the Go server by visiting `/get-jwt`. Make sure to use the same secret key for signing and verifying the JWTs in both the Express and Go servers.

