```javascript
function getSurroundedChar(str) {
  let startIndex = 0;
  let endIndex = 0;

  // Find the first non-space character
  for (let i = 0; i < str.length; i++) {
    if (str[i] !== " ") {
      startIndex = i;
      break;
    }
  }

  // Find the last non-space character
  for (let i = str.length - 1; i >= 0; i--) {
    if (str[i] !== " ") {
      endIndex = i;
      break;
    }
  }

  // Return the surrounded character
  return " " + str[startIndex] + " ";
}
```

