Here's a JavaScript function that takes a string as an argument and returns the index of the first non-space character that is surrounded by spaces:
```javascript
function getFirstNonSpaceSurroundedBySpaces(str) {
  // Create an empty array to store the indices of the first non-space characters
  const indices = [];

  // Loop through the string and mark each non-space character that is surrounded by spaces
  for (let i = 0; i < str.length; i++) {
    if (str[i] !== ' ' && str[i-1] === ' ') {
      // If this is the first non-space character surrounded by spaces, add its index to the array
      if (!indices.includes(i)) {
        indices.push(i);
      }
    } else if (str[i] === ' ' && str[i+1] === ' ') {
      // If this is the last non-space character surrounded by spaces, add its index to the array
      if (!indices.includes(str.length-1)) {
        indices.push(str.length-1);
      }
    }
  }

  // Return the index of the first non-space character surrounded by spaces
  return indices[0];
}
```
