    Circle* circle = (Circle*) shape->ptrShape;
    int radius = circle->radius;
    int x = circle->x;
    int y = circle->y;

    int d = 1 - radius;
    int x1 = 0, y1 = radius;

    while (x1 <= y1) {
        // Upper right and lower left quadrants
        (*pixel_tab)[*nb_pixels] = malloc(sizeof(Pixel));
        (*pixel_tab)[*nb_pixels]->px = x + x1;
        (*pixel_tab)[*nb_pixels]->py = y + y1;
        (*nb_pixels)++;
        (*pixel_tab)[*nb_pixels] = malloc(sizeof(Pixel));
        (*pixel_tab)[*nb_pixels]->px = x + x1;
        (*pixel_tab)[*nb_pixels]->py = y - y1;
        (*nb_pixels)++;

        // Upper left and lower right quadrants
        (*pixel_tab)[*nb_pixels] = malloc(sizeof(Pixel));
        (*pixel_tab)[*nb_pixels]->px = x - x1;
        (*pixel_tab)[*nb_pixels]->py = y + y1;
        (*nb_pixels)++;
        (*pixel_tab)[*nb_pixels] = malloc(sizeof(Pixel));
        (*pixel_tab)[*nb_pixels]->px = x - x1;
        (*pixel_tab)[*nb_pixels]->py = y - y1;
        (*nb_pixels)++;

        if (d < 0) {
            d += 2*x1 + 3;
        } else {
            d += 2*(x1 - y1) + 5;
            y1--;
