    int MSSV;
    char FullName[20];
    int Grade;
};

int main() {
    // create the binary file for storing student information
    ofstream file("input10.bin", ios::out | ios::trunc);
    if (!file.is_open()) {
        cout << "Error creating binary file." << endl;
        return 1;
    }

    // ask the user for the student information
    int MSSV, Grade;
    char FullName[20];
    cout << "Enter MSSV: ";
    cin >> MSSV;
