    cout << "Enter grade: ";
    cin >> Grade;

    // create a student object with the input data
    Student student;
    student.MSSV = MSSV;
    strcpy(student.FullName, FullName);
    student.Grade = Grade;

    // write the student object to the binary file
    file.open("input10.bin", ios::app);
    if (file.is_open()) {
        file.write((const char*)&student, sizeof(Student));
        file.close();
        cout << "Student information saved successfully." << endl;
    }

    return 0;
}
