```rust
use std::time::Duration;
use std::net::TcpStream;
use tokio::io::ReadExt;
use tokio::net::TcpStreamExt;

const PORT: i32 = 8080;
const MAX_BUFFER_SIZE: i32 = 1024;

fn main() {
    let addr = vec![IpAddr::V4::new(0, 0, 0, 0), IpAddr::V4::new(0, 0, 0, 1)];
    let mut stream = TcpStream::connect(&addr).unwrap();

    loop {
        let mut buffer = [0u8; MAX_BUFFER_SIZE];
        stream.read_to_end(&mut buffer).unwrap();
        stream.write_all(&buffer[0..-2]).unwrap();
        stream.write_all(&buffer[0..2]).unwrap();

        let mut buffer = [0u8; MAX_BUFFER_SIZE];
        stream.read_to_end(&mut buffer).unwrap();
        stream.write_all(&buffer[0..-2]).unwrap();
        stream.write_all(&buffer[0..2]).unwrap();

        stream.flush().unwrap();

        if buffer.len() > 0 {
            stream.read_to_end(&mut buffer).unwrap();
        }
    }
}

