#include <cmath>

int countDecimalPlaces(float number, int precision = 0) {
    if (precision > 10 || number == static_cast<int>(number)) {
        return precision;
    }

    return countDecimalPlaces(number * 10, precision + 1);
}

int main() {
    float number = 123.456;

    int decimal_places = countDecimalPlaces(number);

    std::cout << "Approximate decimal places: " << decimal_places << std::endl;

    return 0;
}
