```c
#include <iostream>
#include <algorithm>

using namespace std;

void quicksort(int array[], int left, int right) {
    int i = left;
    int j = right;
    int pivot = array[(left + right) / 2];

    while (i <= j) {
        while (array[i] < pivot) {
            i++;
        }
        while (array[j] > pivot) {
            j--;
        }
        if (i <= j) {
            swap(array[i], array[j]);
            i++;
            j--;
        }
    }

    if (left < j) {
        quicksort(array, left, j);
    }
    if (i < right) {
        quicksort(array, i, right);
    }
}

int main() {
    int array[] = {3, 4, 1, 5, 2};
    int size = sizeof(array) / sizeof(array[0]);

    cout << "Original array: ";
    for (int i = 0; i < size; i++) {
        cout << array[i] << " ";
    }
    cout << endl;

    quicksort(array, 0, size - 1);

    cout << "Sorted array: ";
    for (int i = 0; i < size; i++) {
        cout << array[i] << " ";
    }
    cout << endl;

    return 0;
}
```
This implementation of quicksort takes in an array of integers, and sorts the array in ascending order. The pivot element is chosen as the middle element of the array. The algorithm uses a divide and conquer strategy, recursively dividing the array into two parts and sorting them individually. The time complexity of quicksort is O(n log n) on average, where n is the size of the input array.

