fn quicksort(arr: &[i32], left: usize, right: usize) {
    let mut pivot = arr[(left + right) as usize / 2];
    let mut i = left as usize;
    let mut j = right as usize;

    while i <= j {
        while arr[i] < pivot {
            i += 1;
        }
        while arr[j] > pivot {
            j -= 1;
        }
        if i <= j {
            let temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
            i += 1;
            j -= 1;
        }
    }

    if left < j {
        quicksort(arr, left, j);
    }
    if i < right {
        quicksort(arr, i, right);
    }
}

