Here's a simple C++ program to detect prime numbers using the Sieve of Eratosthenes algorithm. This algorithm works by creating a list of numbers and marking as composite (non-prime) those that have a factor other than 1 and themselves.
```cpp
#include <iostream>
#include <vector>

bool is_prime(int n) {
    if (n <= 1) return false;
    for (int i = 2; i <= sqrt(n); i++) {
        if (n % i == 0) return false;
    }
    return true;
}

int main() {
    int max_num = 100;
    std::vector<int> numbers;

    // Create a vector of numbers from 2 to max_num
    for (int i = 2; i <= max_num; i++) {
        numbers.push_back(i);
    }

    // Mark non-prime numbers as composite
    for (int i = 2; i < sqrt(numbers.back()); i++) {
        if (is_prime(i)) {
            for (int j = i * i; j <= numbers.back(); j += i * i) {
                numbers[j / i] = 0;
            }
        }
    }

    // Print prime numbers
    for (int i = 0; i < numbers.size(); i++) {
        if (numbers[i] == 1) {
            std::cout << i << std::endl;
        }
    }

    return 0;
}
```
This program will output all prime numbers up to the specified maximum number. You can change the `max_num` variable to find prime numbers for a different range.

