```cpp
#include <iostream>
#include <vector>

using namespace std;

int main() {
    int n;
    cin >> n;
    vector<int> a(n);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }

    int min_steps = n;
    int min_diff = INT_MAX;
    for (int i = 1; i < n; i++) {
        int temp = a[0] + i * (n - i - 1) - (n - i);
        for (int j = 0; j < n - i; j++) {
            a[j + i + 1]--;
            temp += a[j + i + 1];
        }

        int diff = temp - (a[0] - (n - i - 1) + 2 * i - (n - i));
        if (diff < min_diff) {
            min_diff = diff;
            min_steps = i;
        }
    }

    cout << min_steps << endl;
    return 0;
}
```
