```rust
fn bubble_sort(arr: &[i32]) {
    let mut n = arr.len();
    while n > 1 {
        for i in 0..n-1 {
            for j in 0..n-i-1 {
                if arr[j] > arr[j + 1] {
                    let temp = arr[j];
                    arr[j] = arr[j + 1];
                    arr[j + 1] = temp;
                }
            }
        }
        n = arr.len();
    }
}
```
