```scss
#include <iostream>
using namespace std;

int fibonacci(int n) {
    if (n <= 0) return 0;
    if (n == 1) return 1;
    int a = 0, b = 1;
    for (int i = 0; i < n; i++) {
        int c = a + b;
        a = b;
        b = c;
    }
    return a;
}

int main() {
    int n;
    cout << "Enter the nth Fibonacci number: ";
    cin >> n;
    cout << fibonacci(n) << endl;
    return 0;
}

```

