  // Get the position of the current avatar
  Vector3f myPosition = getPosition();

  // Create a radius constraint that detects avatars within 10 meters
  Constraint radiusConstraint = new RangeConstraint(
    Vector3f.ZERO, 10.0, myPosition.z);

