// Define a trait for a CSV field
trait Field: Sized + Send + Sync {
    type Name;
    type Value;

    fn name(&self) -> Self::Name;
    fn value(&self) -> Self::Value;
}

// Define a trait for a CSV parser that can parse any fields
trait Parser<F: Field>: Sized + Send + Sync {
    type Error: Error + Send + Sync;

    fn parse_line(&self, line: &str) -> Result<Self::Error, Self::Error>;
    fn from_str(&self, line: &str) -> Result<Self, Self::Error>;
}

// Define a struct for a CSV field
