    id: String,
    point: Point,
    timestamp: Option<Timestamp>,
}

// Define a struct for a CSV parser
struct MyParser<F: Field> {
    fields: F,
}

impl<F: Field> MyParser<F> {
    fn new(fields: F) -> Self {
        Self { fields }
    }

    fn parse_line(&self, line: &str) -> Result<Self::Error, Self::Error> {
        let fields = self.fields.parse_line(line)?;
        Ok(())
    }

    fn from_str(&self, line: &str) -> Result<Self, Self::Error> {
        let fields = self.fields.parse_line(line)?;
        Ok(())
    }
}

// Define a function to parse a CSV file
fn parse_csv<F: Field>(file_path: &str, parser: &mut MyParser<F>) -> Result<(), Box<dyn Error>> {
    let mut reader = std::fs::File::open(file_path)?;
    let mut line = String::new();
    reader.read_line(&mut line)?;
    let line = line.trim();
    let fields = parser.new(Line::parse(line).unwrap())?;
    let mut lines = Vec::new();
    while let Some(line) = std::io::stdin().read_line(&mut line) {
        if let Ok(line) = parser.from_str(line) {
            lines.push(line);
        } else {
            return Err(Box::new(std::io::Error::new(std::io::ErrorKind::Other, "Failed to parse line")));
        }
    }
    Ok(())
}

fn main() -> Result<(), Box<dyn Error>> {
    let file_path = "events.csv";
    let mut parser = MyParser::new(Field::default());
    parse_csv(file_path, &mut parser)?;
    Ok(())
}
