      for (let i = 0; i < n; i++) {
        const pred = this.m * x[i] + this.b;
        const error = y[i] - pred;
        dm += -2 * x[i] * error;
        db += -2 * error;
      }

      this.m -= this.lr * (dm / n);
      this.b -= this.lr * (db / n);
    }
  }

  predict(x) {
    return x.map(val => this.m * val + this.b);
  }
}

