Here's a simple Clang++ program that takes a file path as an argument and creates an MD5 hash of the file:
```c
#include <iostream>
#include <string>
#include <openssl/md5.h>

using namespace std;

int main(int argc, char* argv[]) {
    if (argc != 2) {
        cout << "Usage: md5_hash <filename>\n";
        return 1;
    }

    // Get the file contents
    string file_contents = read_file(argv[1]);

    // Create the MD5 hash
    unsigned char hash[16];
    MD5((unsigned char*)argv[1], strlen(argv[1]), hash);

    // Print the hash
    for (int i = 0; i < 16; i++) {
        cout << hex << setw(2) << setfill('0') << (unsigned int)hash[i] << endl;
    }

    return 0;
}

string read_file(const char* filename) {
    string file_contents;
    ifstream file(filename, ios::in);
    if (file.is_open()) {
        string line;
        while (getline(file, line)) {
            file_contents += line + "\n";
        }
        file.close();
    }
    return file_contents;
}
```
Note that this program uses the OpenSSL library to create the MD5 hash. You will need to include the `openssl/md5.h` header and have the library installed on your system in order for this to work.

Here's a Golang function to pretty print a JSON struct using glog, and print the caller function name:

```go
func PrettyPrintJSON(v interface{}) {
    pc, _, _, _ := runtime.Caller(1)
    caller := runtime.FuncForPC(pc)
    glog.Infof("%s: %+v", caller.Name(), v)

    b, err := json.MarshalIndent(v, "", "  ")
    if err != nil {
        glog.Errorf("%s: error marshaling to JSON: %v", caller.Name(), err)
        return
    }
    glog.Info(string(b))
}
```

This uses the runtime.Caller function to get the caller of this function. It then uses runtime.FuncForPC to get the actual function name of the caller. 
It prints this function name, and the JSON struct v, using glog.
It then marshals the JSON struct to an indented string using json.MarshalIndent, and prints that indented JSON string.

