var TimeLimitedCache = function() {
  this.cache = {};
};

/** 
 * @param {number} key
 * @param {number} value 
 * @param {number} duration
 * @return {boolean} if un-expired key already existed
 */
TimeLimitedCache.prototype.set = function(key, value, duration) {
  if (this.cache[key] && this.cache[key].expiry > Date.now()) {
    this.cache[key].value = value;
    this.cache[key].expiry = Date.now() + duration;
    return true;
  }
  this.cache[key] = {
    value: value, 
    expiry: Date.now() + duration 
  };
  return false;
};

/** 
 * @param {number} key
 * @return {number} value associated with key
 */ 
TimeLimitedCache.prototype.get = function(key) {
  if (this.cache[key] && this.cache[key].expiry > Date.now()) {
    return this.cache[key].value;
  }
  return -1;
};

/**
 * @return {number} count of un-expired keys
 */
TimeLimitedCache.prototype.count = function() {
  let count = 0;
  for (let key in this.cache) {
    if (this.cache[key].expiry > Date.now()) count++;
  }
  return count; 
};
```

This uses an object (this.cache) to store the key-value pairs along with an expiry timestamp. The set(), get() and count() methods check the expiry to determine if the key is still valid.

