If you want to write GPU code without being dependent on a specific vendor's hardware or software, you can use a cross-platform library like OpenCL. OpenCL allows you to write code that can run on GPUs from different vendors, including AMD, NVIDIA, and Intel. 

You can start by downloading and installing the OpenCL SDK for your operating system. Once installed, you can write code in C or C++ and use the OpenCL API to access the GPU. The API provides functions for creating and managing OpenCL contexts, memory objects, and kernels.

Here is a simple example of a vector addition using OpenCL:

```c
#include <stdio.h>
#include <stdlib.h>
#include <CL/cl.h>

#define VECTOR_SIZE 1024

const char* program_source =
"__kernel void vector_add(__global const int* a, __global const int* b, __global int* c)\n"
"{\n"
"    int i = get_global_id(0);\n"
"    c[i] = a[i] + b[i];\n"
"}\n";

int main()
{
    int a[VECTOR_SIZE], b[VECTOR_SIZE], c[VECTOR_SIZE];

    // Initialize input arrays
    for (int i = 0; i < VECTOR_SIZE; i++) {
        a[i] = i;
        b[i] = VECTOR_SIZE - i;
    }

    // Get platform and device
    cl_platform_id platform_id;
    cl_device_id device_id;
    clGetPlatformIDs(1, &platform_id, NULL);
    clGetDeviceIDs(platform_id, CL_DEVICE_TYPE_GPU, 1, &device_id, NULL);

    // Create context and command queue
    cl_context context = clCreateContext(NULL, 1, &device_id, NULL, NULL, NULL);
    cl_command_queue queue = clCreateCommandQueue(context, device_id, 0, NULL);

    // Create and build program
    cl_program program = clCreateProgramWithSource(context, 1, &program_source, NULL, NULL);
    clBuildProgram(program, 1, &device_id, NULL, NULL, NULL);

    // Create kernel and memory objects
    cl_kernel kernel = clCreateKernel(program, "vector_add", NULL);
    cl_mem a_mem = clCreateBuffer(context, CL_MEM_READ_ONLY, VECTOR_SIZE * sizeof(int), NULL, NULL);
    cl_mem b_mem = clCreateBuffer(context, CL_MEM_READ_ONLY, VECTOR_SIZE * sizeof(int), NULL, NULL);
    cl_mem c_mem = clCreateBuffer(context, CL_MEM_WRITE_ONLY, VECTOR_SIZE * sizeof(int), NULL, NULL);

    // Set kernel arguments
    clSetKernelArg(kernel, 0, sizeof(cl_mem), &a_mem);
    clSetKernelArg(kernel, 1, sizeof(cl_mem), &b_mem);
    clSetKernelArg(kernel, 2, sizeof(cl_mem), &c_mem);

    // Enqueue kernel
    size_t global_size = VECTOR_SIZE;
    clEnqueueNDRangeKernel(queue, kernel, 1, NULL, &global_size, NULL, 0, NULL, NULL);

    // Read output buffer
    clEnqueueReadBuffer(queue, c_mem, CL_TRUE, 0, VECTOR_SIZE * sizeof(int), c, 0, NULL, NULL);

    // Print output
    for (int i = 0; i < VECTOR_SIZE; i++) {
        printf("%d + %d = %d\n", a[i], b[i], c[i]);
    }

    // Cleanup
    clReleaseKernel(kernel);
    clReleaseMemObject(a_mem);
    clReleaseMemObject(b_mem);
    clReleaseMemObject(c_mem);
    clReleaseProgram(program);
    clReleaseCommandQueue(queue);
    clReleaseContext(context);

    return 0;
}
```

This code initializes two input arrays `a` and `b` with values ranging from 0 to 1023, creates an OpenCL context, builds a program that contains a kernel for adding the two arrays element-wise, creates memory objects for the input and output data, sets the kernel arguments, enqueues the kernel to the command queue, reads the output buffer, and prints the result. 

Note that this is just a basic example to demonstrate the use of OpenCL. You can use OpenCL to write more complex applications, such as image and video processing, machine learning, and scientific simulations.

