// Decode the JWT into a JavaScript object
const decoded = jwt.split('.')[1];

// Extract the header, payload, and signature fields
const { header, payload, signature } = decoded;

// Use a JWT library to verify the signature
const jwt = require('jsonwebtoken');
const verified = jwt.verify(payload, signature, {
  algorithms: ['RS256'],
  ignoreExpiration: true,
  ignoreNotBefore: true,
});

console.log(verified); // true if the signature is valid, false otherwise
```
