```cpp
class RationalNumber {
public:
    RationalNumber(int num, int den) {
        if (den == 0) {
            throw std::runtime_error("Cannot create rational number with denominator 0");
        }
        if (num == 0 && den != 1) {
            throw std::runtime_error("Cannot create rational number with negative denominator");
        }
        this->num = num;
        this->den = den;
    }

    int getNum() const {
        return num;
    }

    int getDen() const {
        return den;
    }

    friend RationalNumber operator+(const RationalNumber& a, const RationalNumber& b) {
        if (a.getDen() == b.getDen()) {
            return RationalNumber(a.getNum() + b.getNum(), a.getDen());
        } else {
            throw std::runtime_error("Cannot add rational numbers with different denominators");
        }
    }

    friend RationalNumber operator-(const RationalNumber& a, const RationalNumber& b) {
        if (a.getDen() == b.getDen()) {
            return RationalNumber(a.getNum() - b.getNum(), a.getDen());
        } else {
            throw std::runtime_error("Cannot subtract rational numbers with different denominators");
        }
    }

    friend RationalNumber operator*(const RationalNumber& a, const RationalNumber& b) {
        return RationalNumber(a.getNum() * b.getNum() / (a.getDen() * b.getDen()), a.getDen());
    }

    friend bool operator==(const RationalNumber& a, const RationalNumber& b) {
        return a.getNum() * b.getDen() == b.getNum() * a.getDen();
    }

    friend bool operator!=(const RationalNumber& a, const RationalNumber& b) {
        return !(a == b);
    }

private:
    int num;
    int den;
};
