import NAME_5.util.*;

public class MazeSolver {
  private int[][] maze; // the maze as a 2D array of integers
  private int startX, startY, endX, endY; // starting and ending points of the path
  private int dx, dy; // direction of movement

  public MazeSolver(int[][] maze, int startX, int startY, int endX, int endY) {
    this.maze = maze;
    this.startX = startX;
    this.startY = startY;
    this.endX = endX;
    this.endY = endY;
  }

  public boolean findPath() {
    queue<Integer> q = new queue<Integer>(); // use a queue for breadth-first search
    q.add(startX, startY); // add starting point to the queue
    int dx = 0, dy = 0; // initialize movement direction

    while (!q.isEmpty()) {
      int x = q.remove(); // dequeue the next point in the path
      int y = q.remove(); // dequeue the next point in the path

      // check if we've reached the end point
      if (x == endX && y == endY) {
        return true; // found a path!
      }

      // move in the dx, dy direction
      dx += dx;
      dy += dy;

      // add neighboring points to the queue
      for (int[] neighbor : maze[x][y]) {
        q.add(neighbor[0], neighbor[1]); // add x, y as next point in the path
      }
    }

    return false; // didn't find a path
  }
}
