function sortArray(arr) {
  // sort the array in descending order of string length
  arr.sort((a, b) => b.length - a.length);

  // return an object containing the longest and shortest elements
  // and the sorted array
  const result = {
    longest: arr[0],
    shortest: arr[arr.length - 1],
    array: arr
  };

  return result;
}
