Sure! Here's an example implementation of the quicksort algorithm in C++:
```c
#include <iostream>
#include <algorithm>

using namespace std;

void quicksort(int array[], int left, int right) {
    int i = left;
    int j = right;
    int pivot = array[(left + right) / 2];

    while (i <= j) {
        while (array[i] < pivot) {
            i++;
        }

        while (array[j] > pivot) {
            j--;
        }

        if (i <= j) {
            swap(array[i], array[j]);
            i++;
            j--;
        }
    }

    if (left < j) {
        quicksort(array, left, j);
    }

    if (i < right) {
        quicksort(array, i, right);
    }
}

int main() {
    int array[] = {5, 2, 8, 1, 9, 3, 7};
    int size = sizeof(array) / sizeof(array[0]);

    cout << "Before sorting: ";
    for (int i = 0; i < size; i++) {
        cout << array[i] << " ";
    }
    cout << endl;

    quicksort(array, 0, size - 1);

    cout << "After sorting: ";
    for (int i = 0; i < size; i++) {
        cout << array[i] << " ";
    }
    cout << endl;

    return 0;
}
```
In this example, the `quicksort` function takes in an array, a starting left index, and an ending right index. It then chooses a pivot element at the middle of the array and partitions the array into two subarrays, where elements less than the pivot are on the left of the pivot element, and elements greater than the pivot are on the right. The subarrays are then recursively sorted using the same process. Finally, the sorted subarrays are combined to produce the final sorted array.

