```cpp
#include <termios.h>
#include <unistd.h>

int main() {
    struct termios orig_termios;
    struct termios new_termios;

    // Save original terminal settings
    tcgetattr(STDIN_FILENO, &orig_termios);

    // Set new terminal settings for non-canonical mode
    new_termios = orig_termios;
    new_termios.c_lflag &= ~(ICANON | ECHO); // Disable canonical mode and echo
    new_termios.c_cc[VMIN] = 10; // Read 10 chars at a time
    new_termios.c_cc[VTIME] = 0; // No timeout

    // Replace DEL and INT control characters
    new_termios.c_cc[VERASE] = '#';
    new_termios.c_cc[VINTR] = '@';

    // Apply the new settings
    tcsetattr(STDIN_FILENO, TCSANOW, &new_termios);

    // Read input
    char input[10];
    int n = read(STDIN_FILENO, input, 10);
    printf("Read %d chars: %s\n", n, input);

    // Restore original settings
    tcsetattr(STDIN_FILENO, TCSANOW, &orig_termios);
}
```

