```c++
#include <cmath>
// Function to compute the fast inverse square root of a number
double fast_inverse_square_root(double x) {
    const double scale = 0.577350269189; // 1 / sqrt(2)
    const double half = 0.5;
    double a = x, b = scale * x;
    int n = 20;
    while (b < 0.1) {
        b *= 0.5;
        n -= 1;
    }
    double c = sqrt(a / b);
    while (n--) {
        c *= b * b - a;
        if (c >= 0) {
            break;
        }
    }
    return -c / b;
}
```
