Here's an example implementation in Go to find the median of a stream of numbers:
```go
package main

import (
    "container/list"
    "fmt"
)

func findMedian(nums []int) int {
    if len(nums) == 0 {
        return 0
    }

    n := len(nums)
    if n%2 == 0 {
        // even number of elements
        // median is the average of the two middle elements
        return (nums[n/2-1] + nums[n/2]) / 2
    } else {
        // odd number of elements
        // median is the middle element
        return nums[n/2]
    }
}

func main() {
    nums := []int{1, 3, 2, 4, 5, 5, 6, 7, 8, 9}
    fmt.Println(findMedian(nums))
}
