    combined_vector = []
    unique_items = set()

    for item in vector1:
        if item in unique_items:
            continue
        unique_items.add(item)
        combined_vector.append(item)

    for item in vector2:
        if item in unique_items:
            continue
        unique_items.add(item)
        combined_vector.append(item)

    for item in vector3:
        if item in unique_items:
            continue
        unique_items.add(item)
