```c
#include <time.h>
#include <cuda_runtime.h>

__global__ void my_kernel() {
    // your kernel code here
}

int main() {
    int n = 1000;
    int *a;
    cudaMalloc(&a, n * sizeof(int));
    cudaMemcpyToSymbol(a, h_a, n * sizeof(int), cudaMemcpyHostToDevice);

