Here's a function that finds an object by its name deep inside a given object and returns the path used to reach it:
```javascript
function findObjectByName(obj, name, path = []) {
  for (let key in obj) {
    if (obj.hasOwnProperty(key)) {
      if (typeof obj[key] === 'object' && obj[key] !== null) {
        path = path.concat([key]);
        const found = findObjectByName(obj[key], name, path);
        if (found) {
          return { found, path };
        }
      } else if (key === name) {
        return { found: obj[key], path };
      }
    }
  }
  return { notFound: null, path };
}
```
