You can use the Haversine formula to calculate the distance between two geographical points (latitude and longitude) in kilometers. Here's a Node.js code snippet that does just that:
```javascript
const R = 6371e3; // Earth's radius in meters

function haversine(lat1, lon1, lat2, lon2) {
  const phi1 = lat1 * Math.PI / 180;
  const phi2 = lat2 * Math.PI / 180;
  const deltaPhi = (lat2 - lat1) * Math.PI / 180;
  const deltaLambda = (lon2 - lon1) * Math.PI / 180;

  const a = Math.sin(deltaPhi / 2) * Math.sin(deltaPhi / 2) +
      Math.cos(phi1) * Math.cos(phi2) *
      Math.sin(deltaLambda / 2) * Math.sin(deltaLambda / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));

  return R * c;
}

const p1 = { lat: 37.7749, lon: -122.4194 }; // San Francisco
const p2 = { lat: 40.7128, lon: -74.0060 }; // New York

console.log(haversine(p1.lat, p1.lon, p2.lat, p2.lon)); // Approximately 4068.8 km
```
