Here is an example implementation of a thread pool in C++ that allows running arbitrary tasks on a configurable size thread pool:


```c++
#include <iostream>
#include <atomic>
#include <thread>
#include <chrono>
#include <functional>
#include <cstdlib>
#include <pthread.h>

template <typename T>
class Task {
public:
    Task(T* ptr, bool blocking = true) : ptr_(ptr), blocking_(blocking) {}
    Task(T* ptr) : ptr_(ptr), blocking_(false) {}

    ~Task() {
        if (blocking_) {
            std::unique_lock<std::mutex> lock(mut_);
            pthread_join(ptr_->native_handle(), nullptr);
        }
    }

    void run() {
        if (blocking_) {
            std::unique_lock<std::mutex> lock(mut_);
            pthread_create(&ptr_->native_handle(), nullptr, task_func, ptr_);
            pthread_join(ptr_->native_handle(), nullptr);
        } else {
            ptr_->task_func();
        }
    }

private:
    T* ptr_;
    bool blocking_;
    std::mutex mut_;
    pthread_t* ptr_->native_handle_;
    std::atomic<pthread_t> ptr_->native_handle_;
};

class ThreadPool {
public:
    ThreadPool(size_t size) : size_(size), thread_pool_() {}

    void add_task(Task* task) {
        tasks_.push_back(task);
    }

    void run_tasks() {
        while (!tasks_.empty()) {
            std::unique_lock<std::mutex> lock(mut_);
            Task* task = tasks_.front().get();
            tasks_.pop();
            if (task->blocking_) {
                pthread_join(task->native_handle_, nullptr);
            } else {
                task->run();
            }
        }
    }

private:
    size_t size_;

