Here's an example of a quick sort function in C++:


```c++
#include <iostream>

void quickSort(int arr[], int left, int right) {
    if (left < right) {
        int pivot = arr[left];
        int i = left;
        int j = right;

        while (i < j) {
            if (arr[i] < pivot) {
                i++;
            }
            else {
                j--;
            }
            if (i == j) {
                i++;
            }
        }

        int temp = arr[left];
        arr[left] = arr[i];
        arr[i] = temp;

        quickSort(arr, left, j);
        quickSort(arr, j, right);

        arr[left] = arr[i];
        arr[i] = temp;
    }
}

int main() {
    int arr[] = {8, 3, 1, 6, 9, 4, 5, 2, 7, 10};
    int n = sizeof(arr) / sizeof(arr[0]);
    quickSort(arr, 0, n-1);
    for (int i = 0; i < n; i++) {
        std::cout << arr[i] << " ";
    }
    return 0;
}

```

This code implements a basic quick sort algorithm that uses the median of the array to partition the data into two smaller arrays. The pivot is chosen as the middle element of the array. The pivot is swapped with the first element of the smaller array, and the pivot is used to partition the data into two smaller arrays. The smaller arrays are recursively sorted until they are empty, and then the sorted elements are copied back to the original array. The time complexity of this quick sort algorithm is O(n^2), which is a quadratic time complexity.

