using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;

namespace WebAPI.Controllers
{
    [ApiController]
    public class BitmapController : Controller
    {
        private readonly IWebHostEnvironment _env;

        public BitmapController(IWebHostEnvironment env)
        {
            _env = env;
        }

        [HttpPost]
        [Route("api/bitmap")]
        public IActionResult UploadBitmaps()
        {
            List<byte[]> bitmaps = new List<byte[]>();

            // Get all uploaded files from the request
            var files = HttpContext.Request.Form.Files;

            // Process each file
            foreach (var file in files)
            {
                // Validate file size
                if (file.Length > 1048576) // 1 MB
                {
                    return StatusCode(400, "File too large!");
                }

                // Get file path
                var filePath = Path.Combine(_env.WebRootPath, file.FileName);

                // Save file to disk
                using (var stream = new FileStream(filePath, FileMode.Create))
                {
                    file.CopyTo(stream);
                }

                // Read file as byte array
                byte[] bitmap = File.ReadAllBytes(filePath);

                // Add to list
                bitmaps.Add(bitmap); 
            }

            // Return list of byte arrays
            return Ok(bitmaps);
        }
    }
}
