void LineWrappedString::split() {
    unsigned numLines = std::ceil(str.length() / maxCharsPerLine);
    lines.resize(numLines);
    for (unsigned i = 0; i < numLines; ++i) {
        lines[i] = str.substr(i * maxCharsPerLine, maxCharsPerLine);
