Sure, here is an example of binary search in C++:
```cpp
#include <iostream>
using namespace std;

int binarySearch(int arr[], int l, int r, int x) {
  if (r >= l) {
    int mid = l + (r - l) / 2;
    if (arr[mid] == x)
      return mid;
    if (arr[mid] > x)
      return binarySearch(arr, l, mid - 1, x);
    return binarySearch(arr, mid + 1, r, x);
  }
  return -1;
}

int main() {
  int arr[] = {1, 3, 5, 7, 9, 11};
  int n = sizeof(arr) / sizeof(arr[0]);
  int x = 7;
  int result = binarySearch(arr, 0, n - 1, x);
  if (result == -1)
    cout << "Element is not present in the array." << endl;
  else
    cout << "Element is present at index " << result << endl;
  return 0;
}
```
This code takes an array `arr`, its left and right indices `l` and `r`, and the element `x` to be searched. It returns the index of `x` in the array if it is present, or `-1` if it is not present. The function performs a binary search by recursively dividing the search interval in half until the element is found or the search interval is empty.

