import kotlinx.flow.sequential.*

suspend fun quickSort(arr: Array<Int>): Array<Int> {
    if (arr.size < 2) {
        // if the array has less than 2 elements, it's already sorted, so return it as is
        return arr
    }

    // choose the first element as the pivot
    val pivot = arr[0]

    // create a channel to communicate the result of the sort
    val result = Channel<Array<Int>>()

    // start a coroutine to handle the left half of the partition
    GlobalScope.launch {
        val lessThanPivot = mutableListOf<Int>()
        val greaterThanPivot = mutableListOf<Int>()
        for (i in 1..arr.size - 1) {
            if (arr[i] < pivot) {
                lessThanPivot.add(arr[i])
            } else if (arr[i] > pivot) {
                greaterThanPivot.add(arr[i])
            }
        }

        // send the sorted left half to the result channel
        result.send(lessThanPivot)

        // start a coroutine to handle the right half of the partition
        GlobalScope.launch {
            val sortedRightHalf = quickSort(greaterThanPivot)
            result.send(sortedRightHalf)
        }
    }

    // wait for the partitions to finish sorting and receive the result
    val resultFlow = result.receive()
    return resultFlow.fold(
        // if either partition fails to sort, return the failed partition
        { it },
        // if both partitions sort successfully, concatenate them and return the result
        { a, b -> a.concat(b) }
    )
}
```
