```csharp
using System;
using System.Collections.Generic;
using System.IO;

namespace ConsoleApp1
{
    class Program
    {
        static void Main(string[] args)
        {
            // Read the CSV file
            List<string> lines = ReadCSV("file.csv");

            // Do something with the lines...
            foreach (string line in lines)
            {
                Console.WriteLine(line);
            }
        }

        static List<string> ReadCSV(string path)
        {
            List<string> lines = new List<string>();

            // Open the file
            StreamReader reader = new StreamReader(path);

            // Read the file line by line
            string line = reader.ReadLine();
            while (line!= null)
            {
                lines.Add(line);
                line = reader.ReadLine();
            }

            // Close the file
            reader.Close();

            return lines;
        }
    }
}
```
This method takes the path to the CSV file as a parameter and returns a list of strings, each representing a line of the file. The method uses the `StreamReader` class to open the file and read it line by line, then it returns the list of lines.

