A linked list is a data structure that consists of a sequence of nodes, where each node contains a value and a reference (or "link") to the next node in the sequence. Reversing a linked list involves changing the direction of the pointers from next to prev, so that the list appears in reverse order.

Here is an example of how to reverse a linked list in C using a singly linked list:
```c
#include <stdio.h>

struct Node {
    int val;
    struct Node *next;
};

void reverse_list(struct Node *head) {
    struct Node *slow, *fast;

    slow = fast = head;
    while (fast != NULL) {
        struct Node *temp = slow;
        slow = fast;
        fast = temp->next;
    }
    slow->next = NULL;
}

int main() {
    struct Node *head = NULL;
    struct Node *node1 = {1, head};
    struct Node *node2 = {2, node1};
    struct Node *node3 = {3, node2};
    reverse_list(head);
    print_list(head);
    return 0;
}

void print_list(struct Node *head) {
    struct Node *temp = head;
    while (temp != NULL) {
        printf("%d ", temp->val);
        temp = temp->next;
    }
    printf("\n");
}
```
