  const [z, x, y] = v.applyQuaternion([1, 1, 1, 1]);
  const [z, y, x] = w.applyQuaternion([1, 1, 1, 1]);
  const [x, y, z] = u.applyQuaternion([-1, 1, 1, 1]);
  const [x, z, y] = v.applyQuaternion([-1, 1, 1, 1]);
  const [x, z, y] = w.applyQuaternion([-1, 1, 1, 1]);
  return [x, y, z];
}

const projection = projectTriangle(triangle);
