Here is an example of a simple dependency injection engine written in JavaScript:
```javascript
class DependencyInjection {
  constructor() {
    this.dependencies = [];
  }

  register(dependency) {
    this.dependencies.push(dependency);
  }

  resolve(dependencies) {
    const resolver = this.dependencies.reduce((prev, current) => {
      if (current.dependsOn) {
        const dependency = dependencies.find(d => d.name === current.dependsOn);
        if (dependency) {
          return prev.resolve(dependency);
        }
      }
      return prev;
    }, this);

    if (!resolver) {
      throw new Error('Unable to resolve dependency');
    }

    return resolver;
  }
}

