                    Console.WriteLine($"Connection established from {args.RemoteEndPoint}");
                    socket.SendAsync("Current date and time: {DateTime.Now}")
                        .Wait();
                    socket.Disconnect();
                }
                else
                {
                    Console.WriteLine($"Error connecting to {args.RemoteEndPoint}");
                }
            };

            socket.ConnectAsync(socketEventArgs)
                .Wait();
        }
    }

    public void Stop()
    {
        _listener.Stop();
        _thread.Join();
    }
}
```
