```javascript
// Import the AprioriJS library
const Apriori = require('apriori-js');

// Load the dataset into a two-dimensional array
const dataset = [
  ['pizza', 'pepperoni', 'mushrooms', 'cheese'],
  ['pasta', 'spaghetti', 'meatballs', 'tomato sauce'],
  ['salad', 'Caesar', 'grilled chicken', 'avocado'],
  ['sandwich', 'turkey', 'swiss cheese', 'lettuce'],
  ['ice cream', 'chocolate', 'sprinkles', 'whipped cream'],
  ['coffee', 'espresso', 'cinnamon', 'sugar'],
  ['soda', 'cola', 'cherry', 'diet']
];

// Convert the dataset to a one-dimensional array
const oneD = dataset.flat();

// Run the Apriori algorithm with a minimum support of 0.5
const apriori = new Apriori(oneD, { minSupport: 0.5 });

// Extract the frequent itemsets from the Apriori algorithm
const frequentItemsets = apriori.getItemsets();

// Run the Associated Rules algorithm on the frequent itemsets
const rules = apriori.getRules(frequentItemsets);

// Print out the frequent itemsets and associated rules
console.log(frequentItemsets);
console.log(rules);
```
