Sure! Here is an example of how to implement a simple linear regression in Rust using the `ndarray` crate:

```rust
use ndarray::{Array, Array1, Array2, Axis};
use ndarray_linalg::Solve;

pub struct LinearRegression {
    weights: Array1<f64>,
}

impl LinearRegression {
    pub fn new() -> Self {
        LinearRegression { weights: Array::zeros(2) }
    }

    pub fn train(&mut self, x: &Array2<f64>, y: &Array1<f64>) {
        let x_t = x.t().dot(x);
        let x_t_inv = x_t.solve(&Array::eye(2).unwrap()).unwrap();
        self.weights = x_t_inv.dot(&x.t().dot(y));
    }

    pub fn predict(&self, x: &Array2<f64>) -> Array1<f64> {
        x.dot(&self.weights)
    }
}
```

