```c++
#include <iostream>
#include <algorithm>
using namespace std;

struct Int {
    int val;
    int next;
};

void bubbleSort(Int arr[], int n) {
    for (int i = 0; i < n-1; i++) {
        for (int j = 0; j < n-i-1; j++) {
            if (arr[j].val > arr[j+1].val) {
                Int temp(arr[j].val, arr[j].next);
                arr[j].val = arr[j+1].val;
                arr[j+1].val = temp;
            }
        }
    }
}

int main() {
    int arr[] = {8, 6, 5, 4, 3, 1};
    int n = sizeof(arr)/sizeof(arr[0]);
    bubbleSort(arr, n);
    cout << "Sorted array: " << arr << endl;
    return 0;
}

```

