Une fonction de recherche dichotomique est une fonction qui recherche un élément dans une liste en divisant la liste en deux parties égales à chaque fois, jusqu'à ce qu'il trouve l'élément recherché ou qu'il n'y ait plus de parties à diviser. Voici un exemple de fonction de recherche dichotomique en C:
```c
#include <stdio.h>

int rechercheDichotomique(int elements[], int n, int x) {
  int i, j;

  if (n == 0) {
    return -1;
  }

  i = 0;
  j = n - 1;

  while (i <= j) {
    if (elements[i] == x) {
      return i;
    } else if (elements[j] == x) {
      return j;
    } else {
      int mid = (i + j) / 2;
      if (elements[mid] < x) {
        i = mid + 1;
      } else if (elements[mid] > x) {
        j = mid - 1;
      } else {
        i = mid + 1;
        j = mid - 1;
      }
    }
  }

  return -1;
}

int main() {
  int elements[] = {1, 2, 3, 4, 5, 6, 7, 8, 9};
  int n = sizeof(elements) / sizeof(elements[0]);

  int result = rechercheDichotomique(elements, n, 5);

  if (result != -1) {
    printf("Le nombre est à la position %d\n", result);
  } else {
    printf("Le nombre n'a pas été trouvé dans la liste\n");
  }

  return 0;
}
```
